/**
 * Canonical MITRA AI Companion Avatar Helper
 * Embeds the official MITRA robot avatar by default.
 */
export const MITRA_CANONICAL_AVATAR_DATA_URL = 'data:image/png;base64,';

export function renderAvatarElement(avatarDataUrl, className = 'mitra-avatar-media') {
  const src = (avatarDataUrl && avatarDataUrl !== 'default') ? avatarDataUrl : MITRA_CANONICAL_AVATAR_DATA_URL;
  
  const isVideo = src.startsWith('data:video/') || 
                  src.endsWith('.mp4') || 
                  src.endsWith('.webm');
                  
  if (isVideo) {
    const video = document.createElement('video');
    video.className = className;
    video.src = src;
    video.autoplay = true;
    video.loop = true;
    video.muted = true;
    video.playsInline = true;
    video.setAttribute('playsinline', '');
    video.style.width = '100%';
    video.style.height = '100%';
    video.style.objectFit = 'cover';
    video.style.borderRadius = '50%';
    video.style.pointerEvents = 'none';
    video.draggable = false;
    return video;
  } else {
    const img = document.createElement('img');
    img.className = className;
    img.src = src;
    img.alt = 'MITRA';
    img.style.width = '100%';
    img.style.height = '100%';
    img.style.objectFit = 'cover';
    img.style.borderRadius = '50%';
    img.style.pointerEvents = 'none';
    img.draggable = false;
    return img;
  }
}
